package com.xdownload.mobile;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.net.*;import java.nio.file.*;import java.util.concurrent.atomic.*;
public class FtpEngineTest{
 @Test public void validatedPublicUrlsOnly()throws Exception{assertEquals("/a b.zip",FtpEngine.validated("ftps://example.org/a%20b.zip",false).getPath());for(String url:new String[]{"ftp://example.org/a","ftps://user:pass@example.org/a","ftps://example.org/a%0d%0aRETR%20x","ftps://example.org/","ftps://example.org/a?x=y","sftp://example.org/a"})try{FtpEngine.validated(url,false);fail(url);}catch(IOException expected){}}
 @Test public void anonymousPassiveFtpByteExact()throws Exception{byte[] data=new byte[131077];new java.util.Random(3).nextBytes(data);ServerSocket control=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"));AtomicBoolean stop=new AtomicBoolean();Thread server=new Thread(()->{while(!stop.get())try(Socket socket=control.accept()){socket.setSoTimeout(5000);BufferedReader in=new BufferedReader(new InputStreamReader(socket.getInputStream()));PrintWriter out=new PrintWriter(socket.getOutputStream());reply(out,"220 test");ServerSocket transfer=null;try{String line;while((line=in.readLine())!=null){String command=line.split(" ",2)[0];switch(command){case "USER":reply(out,"331 anonymous");break;case "PASS":reply(out,"230 logged in");break;case "TYPE":reply(out,"200 binary");break;case "SIZE":reply(out,"213 "+data.length);break;case "EPSV":if(transfer!=null)transfer.close();transfer=new ServerSocket(0,2,InetAddress.getByName("127.0.0.1"));transfer.setSoTimeout(5000);reply(out,"229 Entering Extended Passive Mode (|||"+transfer.getLocalPort()+"|)");break;case "RETR":reply(out,"150 opening");try(Socket channel=transfer.accept()){channel.getOutputStream().write(data);}transfer.close();transfer=null;reply(out,"226 complete");break;case "QUIT":reply(out,"221 bye");break;default:reply(out,"502 unsupported");}}}finally{if(transfer!=null)transfer.close();}}catch(Exception ignored){}});server.start();File file=File.createTempFile("ftp-public",".part");try{String url="ftp://127.0.0.1:"+control.getLocalPort()+"/data.bin";assertEquals(data.length,FtpEngine.probe(url,true).size);assertEquals(data.length,FtpEngine.download(url,true,file,new HttpEngine.Observer(){public boolean proceed(){return true;}public void progress(long n,long t,String e,String m){}},0));assertArrayEquals(data,Files.readAllBytes(file.toPath()));}finally{stop.set(true);control.close();server.join(3000);file.delete();}}
 static void reply(PrintWriter out,String line){out.print(line+"\r\n");out.flush();}
}